// Helper function to create a test module from source code
func parseTestCode(t *testing.T, src string) *ast.Module {
	l := lexer.NewLexer(src)
	tokens := l.Tokenize()
	p := parser.NewParser(tokens)
	module, err := p.Parse()
	if err != nil {
		t.Fatalf("parser error: %v", err)
	}
	return module
}

