	c.pushScope()

	loopStart := len(c.currentInstructions())
	breakLabel := c.newLabel()
	continueLabel := loopStart

	prevBreak := c.breakLabel
	prevContinue := c.continueLabel
	c.breakLabel = breakLabel
	c.continueLabel = continueLabel

	// Compile condition
