	}

	// Check for jump instructions
	jumpFound := false
	for _, ins := range program.Instructions {
		if ins.Opcode == OpJumpIfFalse || ins.Opcode == OpJump {
			jumpFound = true
			break
		}
	}

	if !jumpFound {
		t.Errorf("expected jump instruction")
	}
}

