	arrayFound := false
	for _, ins := range program.Instructions {
		if ins.Opcode == OpArrayCreate {
			arrayFound = true
			break
		}
	}

	if !arrayFound {
		t.Errorf("expected ARRAY_CREATE instruction")
	}
}

// Test opcode string representation
func TestOpcodeString(t *testing.T) {
