				val := vm.pop()
				if index < len(vm.stack) {
					vm.stack[index] = val
				}
			}
		}

	case compiler.OpAdd:
		right := vm.pop()
		left := vm.pop()
		vm.push(vm.add(left, right))

	case compiler.OpSub:
