		left := vm.pop()
		vm.push(vm.subtract(left, right))

	case compiler.OpMul:
		right := vm.pop()
		left := vm.pop()
		vm.push(vm.multiply(left, right))

	case compiler.OpDiv:
		right := vm.pop()
		left := vm.pop()
		vm.push(vm.divide(left, right))

	case compiler.OpMod:
		right := vm.pop()
		left := vm.pop()
		vm.push(vm.modulo(left, right))

	case compiler.OpEqual:
		right := vm.pop()
		left := vm.pop()
		vm.push(vm.equal(left, right))

	case compiler.OpNotEqual:
		right := vm.pop()
		left := vm.pop()
		vm.push(!vm.equal(left, right).(bool))

	case compiler.OpLess:
		right := vm.pop()
		left := vm.pop()
		vm.push(vm.less(left, right))

	case compiler.OpGreater:
		right := vm.pop()
		left := vm.pop()
		vm.push(vm.greater(left, right))

	case compiler.OpAnd:
		right := vm.pop()
		left := vm.pop()
		vm.push(vm.isTruthy(left) && vm.isTruthy(right))

	case compiler.OpOr:
		right := vm.pop()
		left := vm.pop()
		vm.push(vm.isTruthy(left) || vm.isTruthy(right))

	case compiler.OpNot:
		val := vm.pop()
		vm.push(!vm.isTruthy(val))

	case compiler.OpJump:
		if len(ins.Args) > 0 {
			if target, ok := ins.Args[0].(int); ok {
				return target, nil
			}
		}

	case compiler.OpJumpIfFalse:
		val := vm.pop()
		if len(ins.Args) > 0 && !vm.isTruthy(val) {
			if target, ok := ins.Args[0].(int); ok {
				return target, nil
			}
		}

	case compiler.OpJumpIfTrue:
		val := vm.pop()
		if len(ins.Args) > 0 && vm.isTruthy(val) {
			if target, ok := ins.Args[0].(int); ok {
				return target, nil
			}
		}

	case compiler.OpCall:
		if len(ins.Args) >= 2 {
			fnName := ins.Args[0].(string)
			argCount := ins.Args[1].(int)

			// Get arguments from stack
			args := make([]interface{}, argCount)
			for i := argCount - 1; i >= 0; i-- {
				args[i] = vm.pop()
			}

			// Call function
			if builtin, ok := vm.builtins[fnName]; ok {
				result, err := builtin(args...)
				if err != nil {
					return pc + 1, err
				}
				vm.push(result)
			}
		}

	case compiler.OpArrayCreate:
		if len(ins.Args) > 0 {
			count := ins.Args[0].(int)
			arr := make([]interface{}, count)
			for i := count - 1; i >= 0; i-- {
				arr[i] = vm.pop()
			}
			vm.push(arr)
		}

	case compiler.OpPop:
		vm.pop()

	case compiler.OpReturn:
		vm.retValue = vm.pop()
		vm.isRunning = false

	default:
