func TestDefaultRules(t *testing.T) {
	rules := DefaultRules()

	if !rules.NoUnused {
		t.Errorf("expected NoUnused to be enabled")
	}

	if !rules.NoShadow {
		t.Errorf("expected NoShadow to be enabled")
	}
}

