func BenchmarkAllocation(b *testing.B) {
	gc := NewGC()

	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		gc.Allocate(i, 8, "number")
	}
}

// Benchmark collection
func BenchmarkCollection(b *testing.B) {
	gc := NewGC()

	for i := 0; i < 100; i++ {
		gc.Allocate(i, 8, "number")
	}

	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		gc.Collect()
	}
}

